draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // sea otter
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 30, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 30);
  ctx.lineTo(W/2, H/2 + 60);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 60);
  ctx.lineTo(W/2 - 20, H/2 + 80);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 60);
  ctx.lineTo(W/2 + 20, H/2 + 80);
  ctx.stroke();

  // kelp
  ctx.beginPath();
  ctx.moveTo(W/2 + 20, H/2 + 80);
  ctx.lineTo(W/2 + 20 + 50 * Math.sin(t), H/2 + 150);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 20, H/2 + 80);
  ctx.lineTo(W/2 - 20 + 50 * Math.sin(t + Math.PI), H/2 + 150);
  ctx.stroke();

  // hands holding kelp
  ctx.beginPath();
  ctx.moveTo(W/2 + 20, H/2 + 80);
  ctx.lineTo(W/2 + 20 + 10 * Math.sin(t), H/2 + 100);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 20, H/2 + 80);
  ctx.lineTo(W/2 - 20 + 10 * Math.sin(t + Math.PI), H/2 + 100);
  ctx.stroke();

  ctx.restore();
}
